function bottlesDrunk(full: number, trade: number): number {
  let drunk = full, empty = full;
  while (empty >= trade) {
    const got = Math.floor(empty / trade);
    drunk += got;
    empty = (empty % trade) + got;
  }
  return drunk;
}

